INSERT INTO task_type_template (type_id, locale, render_target, template_text, spec_version)
VALUES
    ('G7-GEO-011', 'ru-KZ', 'plaintext', 'Параллельные прямые пересечены секущей. Один из накрест лежащих внутренних углов равен {{angle}}°. Найдите другой накрест лежащий внутренний угол.', '1.0.0-draft'),
    ('G7-GEO-013', 'ru-KZ', 'plaintext', 'Общий угол разделён на части A и B. A = {{a}}°, а весь угол равен {{total}}°. Найдите величину части B.', '1.0.0-draft'),
    ('G7-GEO-014', 'ru-KZ', 'plaintext', 'Параллельные прямые пересечены секущей. Накрест лежащий внутренний угол равен {{angle}}°. Найдите величину второго накрест лежащего внутреннего угла.', '1.0.0-draft'),
    ('G7-GEO-015', 'ru-KZ', 'plaintext', 'Внешний угол треугольника не смежен с двумя внутренними углами величиной {{a}}° и {{b}}°. Найдите этот внешний угол.', '1.0.0-draft'),
    ('G7-GEO-016', 'ru-KZ', 'plaintext', 'Даны два треугольника со сторонами {{triangles}}. Равны ли они по трём сторонам (признак SSS)?', '1.0.0-draft'),
    ('G7-GEO-017', 'ru-KZ', 'plaintext', 'Два треугольника имеют стороны 4 и 6, а {{angle_info}}. Равны ли они по двум сторонам и углу между ними (признак SAS)?', '1.0.0-draft'),
    ('G7-GEO-018', 'ru-KZ', 'plaintext', 'Соответствующие стороны двух треугольников равны 5 см и 5 см. Равны ли эти соответствующие стороны?', '1.0.0-draft'),
    ('G7-GEO-019', 'ru-KZ', 'plaintext', 'В равнобедренном треугольнике угол при вершине равен {{vertex}}°. Найдите величину каждого угла при основании.', '1.0.0-draft'),
    ('G7-GEO-020', 'ru-KZ', 'plaintext', 'Могут ли числа {{a}}, {{b}} и {{c}} быть длинами сторон треугольника?', '1.0.0-draft'),
    ('G7-GEO-022', 'ru-KZ', 'plaintext', 'Стороны прямоугольника равны {{a}} и {{b}}. Найдите его площадь.', '1.0.0-draft')
